/**
 * smooth-scroll — scroll suave con Lenis, sincronizado con GSAP ScrollTrigger.
 * Conserva el scroll nativo (no es scroll-jacking): solo suaviza la rueda.
 * Familia: scroll · Intensidad 2 (base de ●●● y ●●●●) · deps: lenis, gsap.
 *
 * Se monta una vez, sobre `document.documentElement`. Lenis agrega las clases
 * `lenis` y `lenis-smooth` al <html>; el CSS que recomienda Lenis:
 *
 *   html.lenis, html.lenis body { height: auto; }
 *   .lenis.lenis-smooth { scroll-behavior: auto !important; }
 *   .lenis.lenis-smooth [data-lenis-prevent] { overscroll-behavior: contain; }
 *
 * Según la huella Oblivion va solo en intensidad ●●● o más.
 * Reduced motion: no monta (scroll nativo); cambia en vivo.
 * destroy(): Lenis se destruye (saca sus clases) y GSAP vuelve a su ticker normal.
 */

import Lenis from 'lenis';
import { motionSwitch, type FxHandle } from '../../core/index';
import { fxGsap } from '../../lib/gsap';

export interface SmoothScrollOptions {
  /** Suavizado por frame (0–1). 0.1 es el punto de la casa. */
  lerp?: number;
  wheelMultiplier?: number;
  /** Los links #ancla scrollean con Lenis. */
  anchors?: boolean;
}

export interface SmoothScrollHandle extends FxHandle {
  /** La instancia de Lenis activa (null con reduced motion). */
  readonly lenis: Lenis | null;
  scrollTo(target: string | number | HTMLElement): void;
}

export function createSmoothScroll(_root: HTMLElement = document.documentElement, { lerp = 0.1, wheelMultiplier = 1, anchors = true }: SmoothScrollOptions = {}): SmoothScrollHandle {
  const { gsap, ScrollTrigger } = fxGsap();
  let lenis: Lenis | null = null;

  const off = motionSwitch({
    full: () => {
      const instance = new Lenis({ lerp, wheelMultiplier, anchors, autoRaf: false });
      lenis = instance;
      const onScroll = () => ScrollTrigger.update();
      instance.on('scroll', onScroll);
      const tick = (time: number) => instance.raf(time * 1000);
      gsap.ticker.add(tick);
      gsap.ticker.lagSmoothing(0);
      return () => {
        gsap.ticker.remove(tick);
        gsap.ticker.lagSmoothing(500, 33);
        instance.destroy();
        lenis = null;
      };
    },
  });

  return {
    get lenis() {
      return lenis;
    },
    scrollTo(target) {
      if (lenis) lenis.scrollTo(target as never);
      else if (typeof target === 'number') window.scrollTo({ top: target });
      else (typeof target === 'string' ? document.querySelector(target) : target)?.scrollIntoView();
    },
    destroy: off,
  };
}

'use client';

import type { DependencyList, RefObject } from 'react';
import { useFx } from '../../core/react';
import { createSmoothScroll, type SmoothScrollOptions, type SmoothScrollHandle } from './index';

/**
 * Hook de `smooth-scroll`. Monta sobre `ref.current` y destruye al desmontar.
 * Las opciones se leen al montar; pasá `deps` para volver a montar cuando cambien.
 */
export function useSmoothScroll<E extends HTMLElement>(
  ref: RefObject<E | null>,
  options?: SmoothScrollOptions,
  deps: DependencyList = [],
): RefObject<SmoothScrollHandle | null> {
  return useFx(ref, (el) => createSmoothScroll(el, options), deps);
}

/**
 * GSAP para los efectos del kit. Cada efecto registra solo los plugins que usa
 * (`fxGsap(SplitText)`), así un sitio que usa stacked-cards no carga SplitText
 * ni Flip. Todo lo que crea un efecto va en un `gsap.context()`, y `revert()`
 * deja el DOM como estaba (contrato §2).
 *
 * GSAP es 100% gratis (incluidos SplitText, ScrollTrigger y Flip) desde 2025.
 */

import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

const registered = new Set<unknown>();

/** Registra ScrollTrigger y los plugins pedidos (una sola vez cada uno). */
export function fxGsap(...plugins: object[]) {
  if (typeof window !== 'undefined') {
    for (const plugin of [ScrollTrigger, ...plugins]) {
      if (registered.has(plugin)) continue;
      gsap.registerPlugin(plugin);
      registered.add(plugin);
    }
  }
  return { gsap, ScrollTrigger };
}

/** Curva de la casa como ease de GSAP (equivale a cubic-bezier(0.16, 1, 0.3, 1)). */
export const HOUSE_EASE = 'expo.out';
